    #[test]
    fn each_holder_reads_back_and_meets_the_stray_key_as_measured() {
        let failed: Vec<String> = HOLDERS.iter().flat_map(|holder| holder()).collect();
        assert_eq!(failed, Vec::<String>::new());
    }

    fn holder6() -> Vec<String> {
        check(
            "collide1:C1SX:CA10_SS",
            &rows1(|m0: CA10SS| Holder6Draft { own: 7, m0 }),
            &[("Dot", 'R'), ("Rect", 'R'), ("Wrap", 'R')],
        )
    }

    fn holder14() -> Vec<String> {
        check(
            "collide2:C2N0:CA10_NN|CO11_S nonstrict",
            &rows2(|m0: CA10NN, m1: Option<COI11S>| Holder14Draft { m0, m1 }),
            &[
                ("Dot,None", 'E'),
                ("Dot,Some", 'E'),
                ("Rect,None", 'E'),
                ("Rect,Some", 'E'),
                ("Wrap,None", 'E'),
                ("Wrap,Some", 'E'),
            ],
        )
    }

